import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";
import { parse } from "yaml";
import { METHODS, slugifyWithCounter, specOperations } from "./docs-links.mjs";
import { operationSafety } from "./safety.mjs";

const DEFAULT_OUT_DIR = fileURLToPath(new URL("../skills/monta-api/references/", import.meta.url));

const UNTAGGED = "Other";

const NO_OPERATION_ID = "(none)";

const PARAGRAPH_BREAK = /<\/?br\s*\/?>|\n/i;

const GENERATED_NOTICE =
  "<!-- Generated by scripts/generate-references.mjs from the Monta API OpenAPI spec. Do not edit by hand; regenerate with `npm run generate`. -->";

const SAFETY_LEGEND = "Safety: **R** read-only, **M** mutating (confirm first), **D** destructive (confirm with the concrete target restated).";

const V1_INTRO = `# Monta API v1 endpoints

Every operation in the Monta API v1 spec that is not deprecated, in one file per tag listed below. The Tool column is the operation ID. The hosted MCP server names its tools after it (in Claude Code with the server prefix, for example \`mcp__monta-api__get-charge-points\`), but it only exposes what the credential's scopes allow and leaves a few operations out, so search for a tool before concluding it is missing. Deprecated operations and their replacements are in \`deprecated.md\`.

${SAFETY_LEGEND}`;

const V2_INTRO = `# Monta API v2 endpoints (HTTP only)

Every operation in the Monta API v2 spec that is not deprecated, in one file per tag listed below. The hosted MCP server serves v1 only, so none of these operations is an MCP tool. Use them in code the partner writes, which calls them over HTTP with its own credentials and the \`Monta-Version: v2\` header; the paths keep the \`/api/v1\` prefix. Never ask for a token or secret in the chat. v2 is in beta and may change without notice, see [API versioning](https://developer.monta.com/docs/api-versioning). The Operation ID column only identifies the operation in the spec. Deprecated operations are in \`deprecated.md\`.

${SAFETY_LEGEND}`;

const ENDPOINT_INDEXES = {
  v1: {
    indexFile: "endpoints.md",
    intro: V1_INTRO,
    tagIntro: `The Tool column is the MCP tool name, see \`../../endpoints.md\`. ${SAFETY_LEGEND}`,
    operationIdHeader: "Tool",
  },
  v2: {
    indexFile: "endpoints-v2.md",
    intro: V2_INTRO,
    tagIntro: `HTTP only with the \`Monta-Version: v2\` header, none of these is an MCP tool, see \`../../endpoints-v2.md\`. ${SAFETY_LEGEND}`,
    operationIdHeader: "Operation ID",
  },
};

const DEPRECATED_INTRO = `# Deprecated Monta API operations

Operations the Monta API spec marks as deprecated. Do not use them for new work. The note quotes the spec, which names the replacement when there is one.`;

const SCHEMAS_INTRO = `# Monta API schemas

Component schemas of the Monta API spec: the first sentence of each description and the required fields.`;

const ENDPOINT_HEADERS = ["Method and path", "Summary", "Query filters", "Safety", "Docs"];

// UTF-16 code-unit order, so the output does not depend on the ICU version of the Node that generates it
const byText = (a, b) => {
  if (a === b) {
    return 0;
  }
  return a < b ? -1 : 1;
};

const byPathThenMethod = (a, b) => byText(a.path, b.path) || METHODS.indexOf(a.method) - METHODS.indexOf(b.method);

const escapeCell = (text) => text.replace(/\s*\n\s*/g, " ").replaceAll("|", "\\|").trim();

const tableRow = (cells) => `| ${cells.map(escapeCell).join(" | ")} |`;

const table = (headers, rows) => [tableRow(headers), `|${headers.map(() => "---").join("|")}|`, ...rows.map(tableRow)].join("\n");

const generatedFile = (intro, sections) => `${[GENERATED_NOTICE, intro, ...sections].join("\n\n")}\n`;

const paragraphs = (text) =>
  text
    .split(PARAGRAPH_BREAK)
    .map((paragraph) => paragraph.trim())
    .filter((paragraph) => paragraph !== "");

const deprecationNote = (description) => {
  const deprecationParagraphs = paragraphs(description).filter((paragraph) => /deprecat/i.test(paragraph));
  if (deprecationParagraphs.length === 0) {
    return description;
  }
  return deprecationParagraphs.join(" ");
};

const firstSentence = (description) => {
  const [firstParagraph = ""] = paragraphs(description);
  return firstParagraph.split(/(?<=\.)\s/)[0];
};

const indexedOperations = (spec, version) =>
  specOperations(spec, version).map(({ method, path, operation, docsUrl }) => ({
    method,
    path,
    tag: operation.tags?.[0] ?? UNTAGGED,
    operationId: operation.operationId ?? NO_OPERATION_ID,
    summary: operation.summary ?? "",
    description: operation.description ?? "",
    queryFilters: (operation.parameters ?? []).filter((parameter) => parameter.in === "query").map(({ name }) => name),
    safety: operationSafety(method, operation.operationId),
    deprecated: operation.deprecated === true,
    docsLink: `[docs](${docsUrl})`,
  }));

const methodAndPath = ({ method, path }) => `${method.toUpperCase()} ${path}`;

const endpointRow = (operation) => [
  operation.operationId,
  methodAndPath(operation),
  operation.summary,
  operation.queryFilters.join(", "),
  operation.safety,
  operation.docsLink,
];

const endpointFiles = (version, operations) => {
  const { indexFile, intro, tagIntro, operationIdHeader } = ENDPOINT_INDEXES[version];
  const currentOperations = operations.filter(({ deprecated }) => !deprecated);
  const operationsByTag = Map.groupBy(currentOperations, ({ tag }) => tag);
  const tagFileSlug = slugifyWithCounter();
  const tags = [...operationsByTag.keys()].sort(byText).map((tag) => ({
    tag,
    operations: operationsByTag.get(tag).toSorted(byPathThenMethod),
    file: `endpoints/${version}/${tagFileSlug(tag)}.md`,
  }));
  const indexRows = tags.map(({ tag, operations, file }) => [tag, String(operations.length), `[${file}](${file})`]);
  const tagFiles = tags.map(({ tag, operations, file }) => {
    const endpointTable = table([operationIdHeader, ...ENDPOINT_HEADERS], operations.map(endpointRow));
    return [file, generatedFile(`# ${tag} (${version})\n\n${tagIntro}`, [endpointTable])];
  });
  return [[indexFile, generatedFile(intro, [table(["Tag", "Operations", "File"], indexRows)])], ...tagFiles];
};

const deprecatedSection = (version, operations) => {
  const rows = operations
    .filter(({ deprecated }) => deprecated)
    .toSorted(byPathThenMethod)
    .map((operation) => [operation.operationId, methodAndPath(operation), deprecationNote(operation.description), operation.docsLink]);
  return `## ${version}\n\n${table(["Operation ID", "Method and path", "Deprecation note", "Docs"], rows)}`;
};

const schemasSection = (version, spec) => {
  const schemas = Object.entries(spec.components?.schemas ?? {});
  const rows = schemas
    .toSorted(([a], [b]) => byText(a, b))
    .map(([name, schema]) => [name, firstSentence(schema.description ?? ""), (schema.required ?? []).join(", ")])
    .filter(([, description, requiredFields]) => description !== "" || requiredFields !== "");
  return `## ${version}\n\n${table(["Name", "Description", "Required fields"], rows)}`;
};

export const renderReferences = ({ v1Spec, v2Spec }) => {
  const v1Operations = indexedOperations(v1Spec, "v1");
  const v2Operations = indexedOperations(v2Spec, "v2");
  return {
    ...Object.fromEntries(endpointFiles("v1", v1Operations)),
    ...Object.fromEntries(endpointFiles("v2", v2Operations)),
    "deprecated.md": generatedFile(DEPRECATED_INTRO, [deprecatedSection("v1", v1Operations), deprecatedSection("v2", v2Operations)]),
    "schemas.md": generatedFile(SCHEMAS_INTRO, [schemasSection("v1", v1Spec), schemasSection("v2", v2Spec)]),
  };
};

// Clears the tag files first, so a tag dropped from the spec loses its file
export const writeReferences = (outDir, references) => {
  rmSync(join(outDir, "endpoints"), { recursive: true, force: true });
  for (const [file, content] of Object.entries(references)) {
    const filePath = join(outDir, file);
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, content);
  }
};

const fetchSpec = async (version) => {
  const response = await fetch(`https://partner-api.monta.com/swagger/monta-partner-api-${version}.yml`);
  if (!response.ok) {
    throw new Error(`Fetching the ${version} spec failed with HTTP ${response.status}`);
  }
  return response.text();
};

const loadSpec = async (version) => {
  const specText = await fetchSpec(version);
  return parse(specText);
};

const main = async () => {
  const { values } = parseArgs({
    options: {
      out: { type: "string", default: DEFAULT_OUT_DIR },
    },
  });
  const v1Spec = await loadSpec("v1");
  const v2Spec = await loadSpec("v2");
  const references = renderReferences({ v1Spec, v2Spec });
  writeReferences(values.out, references);
};

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await main();
}
